// GENERATED by crashtest. Scripted responder for eve's mockModel: it drives each run so the agent
// calls exactly one tool, and behaves like a model that reacts to eve's interrupted-attempt note.
// This file is copied verbatim into the lab, so it may only import node built-ins.
import { readFileSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";

export interface ResponderScript {
  /** The tool under test. */
  tool: string;
  /** The input of the call; its identity fields stay the same on every emission. */
  input: Record<string, unknown>;
  /** "stable": eve derives the call id. "fresh": every emission gets a new id. */
  idMode: "stable" | "fresh";
  /** Input keys whose string value a model would word differently on a replay. */
  freeTextFields: string[];
}

interface ResponderState {
  emits: number;
  retried: boolean;
  /** The first error result of the tool under test, such as an input the AI SDK rejected before the tool ran. */
  firstToolError?: string;
}

interface ResponderRequest {
  messages: readonly { role: string; text: string }[];
  /** As eve's `MockModelToolResult`: `isError` is true for a failed or denied call. */
  toolResults: readonly { name: string; output: unknown; isError: boolean }[];
}

type ResponderResponse = string | { toolCalls: { name: string; input: unknown; id?: string }[] };

const DONE = "crashtest: done";
const ERROR_CHARS = 500;

function readJson(path: string): unknown {
  return JSON.parse(readFileSync(path, "utf8"));
}

function isMissing(error: unknown): boolean {
  return typeof error === "object" && error !== null && (error as { code?: unknown }).code === "ENOENT";
}

function loadScript(runDir: string): ResponderScript {
  const script = readJson(join(runDir, "script.json")) as Partial<ResponderScript> | null;
  if (
    typeof script !== "object" ||
    script === null ||
    typeof script.tool !== "string" ||
    typeof script.input !== "object" ||
    script.input === null ||
    (script.idMode !== "stable" && script.idMode !== "fresh")
  ) {
    throw new Error(`crashtest responder: ${join(runDir, "script.json")} is not a valid script`);
  }
  return { tool: script.tool, input: script.input, idMode: script.idMode, freeTextFields: script.freeTextFields ?? [] };
}

function loadState(runDir: string): ResponderState {
  try {
    const state = readJson(join(runDir, "responder.json")) as Partial<ResponderState>;
    const firstToolError = typeof state.firstToolError === "string" ? { firstToolError: state.firstToolError } : {};
    return { emits: Number(state.emits) || 0, retried: state.retried === true, ...firstToolError };
  } catch (error) {
    if (isMissing(error)) return { emits: 0, retried: false };
    throw error;
  }
}

// Synchronous and atomic: the process can be killed right after the model call returns.
function saveState(runDir: string, state: ResponderState): void {
  const path = join(runDir, "responder.json");
  const tmp = `${path}.${process.pid}.tmp`;
  writeFileSync(tmp, JSON.stringify(state));
  renameSync(tmp, path);
}

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** The note's line about `tool`, from the latest user message eve wrote after an interrupted attempt. */
function interruptedLine(messages: ResponderRequest["messages"], tool: string): string | null {
  const line = new RegExp(`^- ${escapeRegExp(tool)}[ :].*$`, "m");
  for (let i = messages.length - 1; i >= 0; i--) {
    const message = messages[i]!;
    if (message.role !== "user" || !message.text.includes("interrupted your previous attempt")) continue;
    const match = line.exec(message.text);
    if (match) return match[0];
  }
  return null;
}

/** A tool output as text: text as it is, anything else as JSON, at most `ERROR_CHARS` characters. */
function outputText(output: unknown): string {
  const text = typeof output === "string" ? output : (JSON.stringify(output) ?? String(output));
  return text.slice(0, ERROR_CHARS);
}

function perturb(input: Record<string, unknown>, fields: readonly string[], emits: number): Record<string, unknown> {
  const out = { ...input };
  for (const key of fields) {
    const value = out[key];
    if (typeof value === "string") out[key] = `${value} (rewritten ${emits})`;
  }
  return out;
}

export function createResponder(env: { runDir?: string; pid?: number } = {}): (req: ResponderRequest) => ResponderResponse {
  return (req) => {
    const runDir = env.runDir ?? process.env.CT_RUN_DIR;
    if (!runDir) throw new Error("crashtest responder: CT_RUN_DIR is not set");
    const pid = env.pid ?? process.pid;
    const script = loadScript(runDir);
    const state = loadState(runDir);

    // Before any answer: a call whose input the AI SDK rejected never reaches eve's stream, and this error result is
    // its only trace. Crashtest reads it from responder.json after the run.
    const failed = req.toolResults.find((result) => result.name === script.tool && result.isError);
    if (failed !== undefined && state.firstToolError === undefined) {
      state.firstToolError = outputText(failed.output);
      saveState(runDir, state);
    }

    const emit = (mode: "stable" | "fresh"): ResponderResponse => {
      state.emits += 1;
      saveState(runDir, state);
      if (mode === "stable") return { toolCalls: [{ name: script.tool, input: script.input }] };
      const input = state.emits > 1 ? perturb(script.input, script.freeTextFields, state.emits) : script.input;
      return { toolCalls: [{ name: script.tool, id: `ct-call-${state.emits}-${pid}`, input }] };
    };

    const line = interruptedLine(req.messages, script.tool);
    if (line !== null) {
      if (line.includes("may or may not have taken effect") && !state.retried) {
        state.retried = true;
        return emit("fresh");
      }
      return DONE;
    }
    if (!req.toolResults.some((result) => result.name === script.tool)) return emit(script.idMode);
    return DONE;
  };
}
